#[tokio::test]
async fn unconfirmed_termination_retains_the_same_process_owner() -> anyhow::Result<()> {
    let manager = UnifiedExecProcessManager::default();
    let process_id = manager.allocate_process_id().await;
    let process = Arc::new(
        crate::unified_exec::process_tests::remote_process(
            codex_exec_server::WriteStatus::Accepted,
            /*terminate_error*/ None,
            codex_sandboxing::SandboxType::None,
        )
        .await,
    );
    manager.process_store.lock().await.processes.insert(
        process_id,
        ProcessEntry {
            process: Arc::clone(&process),
            plugin_metrics_sidecar: None,
            call_id: "unconfirmed-termination".to_string(),
            process_id,
            cwd: PathUri::parse("file:///unified-exec-test")?,
            initial_exec_command_active: Arc::new(AtomicBool::new(false)),
            hook_command: "controlled-process".to_string(),
            tty: false,
            network_approval: None,
            session: std::sync::Weak::new(),
            last_used: Instant::now(),
        },
    );

    let terminated = tokio::time::timeout(
        Duration::from_secs(2),
        manager.terminate_process(process_id),
    )
    .await?;
    assert!(!terminated);
    assert!(!process.has_exited());
    assert_eq!(process.exit_code(), None);
    let store = manager.process_store.lock().await;
    let retained = store
        .processes
        .get(&process_id)
        .ok_or_else(|| anyhow::anyhow!("unconfirmed owner was removed"))?;
    assert_eq!(store.processes.len(), 1);
    assert!(Arc::ptr_eq(&retained.process, &process));
    Ok(())
}

#[tokio::test]
async fn termination_waits_for_the_drivers_later_native_result() -> Result<()> {
    let fixture = driver_fixture();
    let process = UnifiedExecProcess::from_spawned(
        fixture.spawned,
        SandboxType::None,
        Box::new(NoopSpawnLifecycle),
    )
    .await?;
    let termination = process.terminate_confirmed(Instant::now() + Duration::from_secs(1));
    tokio::pin!(termination);

    assert!(futures::poll!(&mut termination).is_pending());
    assert_eq!(fixture.terminations.load(Ordering::SeqCst), 1);
    assert_eq!(*process.state_rx.borrow(), ProcessState::default());
    fixture
        .exit_tx
        .send(53)
        .map_err(|_| anyhow::anyhow!("native exit receiver closed during confirmation"))?;
    tokio::time::timeout(Duration::from_secs(2), &mut termination).await??;

    assert_eq!(
        *process.state_rx.borrow(),
        ProcessState {
            has_exited: true,
            exit_code: Some(53),
            ..ProcessState::default()
        }
    );
    assert_eq!(fixture.terminations.load(Ordering::SeqCst), 1);
    Ok(())
}

#[tokio::test]
async fn termination_without_a_native_driver_result_remains_indeterminate() -> Result<()> {
    let fixture = driver_fixture();
    let process = UnifiedExecProcess::from_spawned(
        fixture.spawned,
        SandboxType::None,
        Box::new(NoopSpawnLifecycle),
    )
    .await?;
    let termination = process.terminate_confirmed(Instant::now() + Duration::from_secs(1));
    tokio::pin!(termination);

    assert!(futures::poll!(&mut termination).is_pending());
    assert_eq!(fixture.terminations.load(Ordering::SeqCst), 1);
    let error = tokio::time::timeout(Duration::from_secs(2), &mut termination)
        .await?
        .expect_err("requesting termination does not supply the missing native result");
    assert!(error.to_string().contains(TERMINATION_NOT_OBSERVED));
    assert_eq!(
        *process.state_rx.borrow(),
        ProcessState {
            failure_message: Some(TERMINATION_NOT_OBSERVED.to_string()),
            ..ProcessState::default()
        }
    );

    // The deadline must not destroy the original native-result observer.
    fixture
        .exit_tx
        .send(59)
        .map_err(|_| anyhow::anyhow!("native exit receiver closed after the deadline"))?;
    let mut state_rx = process.state_rx.clone();
    tokio::time::timeout(
        Duration::from_secs(2),
        state_rx.wait_for(|state| state.has_exited),
    )
    .await??;
    assert_eq!(
        *process.state_rx.borrow(),
        ProcessState {
            has_exited: true,
            exit_code: Some(59),
            failure_message: Some(TERMINATION_NOT_OBSERVED.to_string()),
            ..ProcessState::default()
        }
    );
    assert_eq!(fixture.terminations.load(Ordering::SeqCst), 1);
    Ok(())
}

#[tokio::test]
async fn successful_ack_waits_for_a_later_native_exit() -> Result<()> {
    let fixture = RemoteFixture::new(WriteStatus::Accepted).await?;
    let termination = fixture
        .process
        .terminate_confirmed(Instant::now() + Duration::from_secs(1));
    tokio::pin!(termination);
    assert!(futures::poll!(&mut termination).is_pending());
    fixture.wait_for_termination().await?;

    fixture.release_ack();
    // Poll the released ACK through the caller before publishing any exit.
    assert!(futures::poll!(&mut termination).is_pending());
    assert_eq!(*fixture.process.state_rx.borrow(), ProcessState::default());
    fixture.exited(61)?;
    tokio::time::timeout(Duration::from_secs(2), &mut termination).await??;

    assert_eq!(
        *fixture.process.state_rx.borrow(),
        ProcessState {
            has_exited: true,
            exit_code: Some(61),
            ..ProcessState::default()
        }
    );
    assert_eq!(*fixture.remote.termination_started.borrow(), 1);
    Ok(())
}

#[tokio::test]
async fn termination_request_deadline_keeps_the_native_observer_alive() -> Result<()> {
    let fixture = RemoteFixture::new(WriteStatus::Accepted).await?;
    let termination = fixture
        .process
        .terminate_confirmed(Instant::now() + Duration::from_secs(1));
    tokio::pin!(termination);
    assert!(futures::poll!(&mut termination).is_pending());
    fixture.wait_for_termination().await?;

    // Keep the original request blocked: no ACK or native exit has arrived.
    let error = tokio::time::timeout(Duration::from_secs(2), &mut termination)
        .await?
        .expect_err("the request and exit observation share a finite budget");
    assert!(error.to_string().contains(TERMINATION_REQUEST_DEADLINE_ELAPSED));
    assert!(!fixture.process.has_exited());
    assert_eq!(fixture.process.exit_code(), None);
    assert_eq!(*fixture.remote.termination_started.borrow(), 1);

    fixture.exited(67)?;
    fixture.wait_for_state(|state| state.has_exited).await?;
    assert_eq!(fixture.process.exit_code(), Some(67));
    assert_eq!(*fixture.remote.termination_started.borrow(), 1);
    Ok(())
}

#[tokio::test]
async fn retained_observation_failure_wins_when_cleanup_exceeds_its_deadline() -> Result<()> {
    let fixture = RemoteFixture::new(WriteStatus::Accepted).await?;
    fixture.remote.events.send(ExecProcessEvent::Failed(
        "original observer failed".to_string(),
    ))?;
    fixture
        .wait_for_state(|state| state.failure_message.is_some())
        .await?;
    let termination = fixture
        .process
        .terminate_confirmed(Instant::now() + Duration::from_secs(1));
    tokio::pin!(termination);
    assert!(futures::poll!(&mut termination).is_pending());
    fixture.wait_for_termination().await?;

    let error = tokio::time::timeout(Duration::from_secs(2), &mut termination)
        .await?
        .expect_err("cleanup must retain the original observation failure");
    assert!(error.to_string().contains("original observer failed"));
    assert_eq!(
        *fixture.process.state_rx.borrow(),
        ProcessState {
            failure_message: Some("original observer failed".to_string()),
            ..ProcessState::default()
        }
    );
    assert_eq!(*fixture.remote.termination_started.borrow(), 1);
    Ok(())
}
